task-01-excerpt:
def clamp_excerpt(value, limit):
    """Return an excerpt whose total display width stays within limit."""
    if limit <= 0:
        return ""
    if len(value) <= limit:
        return value
    if limit <= 3:
        return "." * limit
    return value[:limit - 3] + "..."

task-02-relative-path:
def relative_path(path, root):
    """Return path under root, rejecting siblings that merely share its prefix."""
    clean_root = root.rstrip("/")
    if path == clean_root:
        return ""
    if path.startswith(clean_root + "/"):
        return path[len(clean_root):].lstrip("/")
    raise ValueError("path is outside root")

task-04-retry-delays:
def retry_delays(attempts, base_seconds):
    """Produce exponential retry delays for the requested number of retries."""
    if attempts < 0 or base_seconds < 0:
        raise ValueError("attempts and base_seconds must be non-negative")
    return [base_seconds * (2 ** attempt) for attempt in range(attempts)]

task-05-coerce-flag:
def coerce_flag(value):
    """Coerce common textual flags without accepting ambiguous arbitrary strings."""
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"true", "yes", "1", "on"}:
            return True
        if normalized in {"false", "no", "0", "off"}:
            return False
    raise ValueError("not a boolean flag")

task-06-replace-parameter:
def replace_parameter(query, key, value):
    """Replace all copies of key, or append it if key is absent."""
    pairs = parse_pairs(query)
    found = False
    output = []
    for name, old_value in pairs:
        if name == key:
            if not found:
                output.append((key, value))
                found = True
        else:
            output.append((name, old_value))
    if not found:
        output.append((key, value))
    return "&".join(f"{name}={item}" for name, item in output)

task-07-within:
def within(value, target, tolerance):
    """Check inclusive distance and reject a negative tolerance."""
    if tolerance < 0:
        raise ValueError("tolerance must be non-negative")
    return abs(value - target) <= tolerance

task-08-header-value:
def safe_header_value(value):
    """Reject CR/LF so a value cannot create a second HTTP header."""
    if "\r" in value or "\n" in value:
        raise ValueError("header value contains a line break")
    return value.strip()
